struct command * ibmasm_new_command ( struct service_processor * sp , size_t buffer_size ) { struct command * cmd ; cmd = kzalloc ( sizeof ( command ) , GFP_KERNEL ) ; if ( cmd == NULL ) { return NULL ; } cmd -> buffer = kzalloc ( buffer_size , GFP_KERNEL ) ; if ( cmd -> buffer == NULL ) { kfree ( cmd ) ; return NULL ; } cmd -> buffer_size = buffer_size ; kref_init ( & cmd -> kref ) ; cmd -> lock = & sp -> lock ; cmd -> status = IBMASM_CMD_PENDING ; init_waitqueue_head ( & cmd -> wait ) ; INIT_LIST_HEAD ( & cmd -> queue_node ) ; atomic_inc ( & command_count ) ; dbg ( "command count: %d\n" , atomic_read ( & command_count ) ) ; return cmd ; } 